import jwt from 'jsonwebtoken';

function autenticar(req) {
  const token = req.headers.authorization?.replace('Bearer ', '');
  const payload = jwt.decode(token);
  if (!payload) throw new ErroNaoAutenticado();
  return payload.sub;
}

