async function buscarProduto(id) {
  const cache = await redis.get(`produto:${id}`);
  if (cache) return JSON.parse(cache);
  const produto = await db.produtos.buscar(id);
  await redis.set(`produto:${id}`, JSON.stringify(produto));
  return produto;
}

