import { db } from '../db.js';

export class PedidosService {
  async total(clienteId) {
    const pedidos = await db.query('SELECT total FROM pedidos WHERE cliente_id = $1', [clienteId]);
    return pedidos.reduce((s, p) => s + p.total, 0);
  }
}

